import json
import random
import unittest
from unittest.mock import patch

import pandas as pd

import config
import recommender


def evaluation_fixture():
    """Return 200 identifiable rows with a 40% positive share and varying numeric scales."""
    rng = random.Random(config.RANDOM_SEED)
    y = pd.Series([int(i % 5 < 2) for i in range(200)], name='label')
    rows = []
    for i, label in enumerate(y):
        rows.append({'focus': label + rng.uniform(-1, 1), 'duration': rng.randrange(60, 180),
                     'favorite': i % 2, 'price': rng.randrange(40)})
    return pd.DataFrame(rows), y


class EvaluationTests(unittest.TestCase):
    """Exercise actual classifiers while tracing which rows reach fitting and scaling."""

    def test_split_is_stratified_disjoint_and_seeded(self):
        """Verify exact 80/10/10 sizes, both label proportions and the seed-13 membership."""
        X, y = evaluation_fixture()
        with patch.object(recommender, 'train_test_split',
                          wraps=recommender.train_test_split) as split:
            train, val, test, y_train, y_val, y_test = recommender._split_for_evaluation(X, y)
        self.assertEqual([len(train), len(val), len(test)], [160, 20, 20])
        for labels in (y_train, y_val, y_test):
            self.assertAlmostEqual(labels.mean(), 0.4)
        indices = [set(frame.index) for frame in (train, val, test)]
        self.assertFalse(indices[0] & indices[1] or indices[0] & indices[2]
                         or indices[1] & indices[2])
        self.assertEqual(set.union(*indices), set(X.index))
        again = recommender._split_for_evaluation(X, y)
        for left, right in zip((train, val, test), again[:3]):
            pd.testing.assert_frame_equal(left, right)
        self.assertEqual([call.kwargs['random_state'] for call in split.call_args_list], [13, 13])
        self.assertEqual([call.kwargs['test_size'] for call in split.call_args_list], [0.2, 0.5])
        for call in split.call_args_list:
            self.assertIs(call.kwargs['stratify'], call.args[1])

    def test_ten_variants_scaler_train_only_and_forest_test_boundary(self):
        """Use a single train-only scaler and report the forest that never fitted test rows."""
        X, y = evaluation_fixture()
        original = X.copy(deep=True)
        train, val, test, y_train, _, y_test = recommender._split_for_evaluation(X, y)
        scaler = recommender.RobustScaler()
        forests = [recommender._comparison_models()['Random Forest'] for _ in range(2)]
        with patch.object(recommender, 'RobustScaler', return_value=scaler), \
                patch.object(scaler, 'fit', wraps=scaler.fit) as fit_scaler, \
                patch.object(scaler, 'transform', wraps=scaler.transform) as transform, \
                patch.object(recommender, 'RandomForestClassifier', side_effect=forests), \
                patch.object(forests[0], 'fit', wraps=forests[0].fit) as fit_forest:
            result = recommender.evaluate_models(X, y)
        self.assertEqual(list(result.columns), list(config.EVALUATION_COLUMNS))
        self.assertEqual(len(result), 10)
        self.assertTrue(result.attrs['available'])
        self.assertEqual(result.groupby('model')['scaled'].agg(list).tolist(), [[False, True]] * 5)
        self.assertTrue(result.iloc[:, 2:].ge(0).all().all())
        self.assertTrue(result.iloc[:, 2:].le(1).all().all())
        fit_scaler.assert_called_once()
        pd.testing.assert_frame_equal(fit_scaler.call_args.args[0], train)
        self.assertEqual(transform.call_count, 3)
        for call, frame in zip(transform.call_args_list, (train, val, test)):
            pd.testing.assert_frame_equal(call.args[0], frame)
        fit_forest.assert_called_once()
        self.assertEqual(fit_forest.call_args.kwargs, {})
        pd.testing.assert_frame_equal(fit_forest.call_args.args[0], train)
        pd.testing.assert_series_equal(fit_forest.call_args.args[1], y_train)
        expected = recommender.accuracy_score(y_test, forests[0].predict(test))
        self.assertAlmostEqual(result.attrs['test_metrics']['accuracy'], expected)
        self.assertIn('macro avg', result.attrs['classification_report'])
        self.assertEqual(result.attrs['split_sizes'], {'train': 160, 'validation': 20, 'test': 20})
        json.dumps(result.attrs, allow_nan=False)
        pd.testing.assert_frame_equal(X, original)
        self.assertAlmostEqual(sum(row['importance'] for row in
                                   result.attrs['feature_importances']), 1)

    def test_required_classifier_parameters(self):
        """Keep the specified five model families, forest settings and fixed random seeds."""
        models = recommender._comparison_models()
        self.assertEqual(len(models), 5)
        self.assertEqual(models['Random Forest'].n_estimators, 200)
        self.assertEqual(models['Random Forest'].max_depth, 10)
        self.assertEqual(models['Logistic Regression'].max_iter, 1000)
        self.assertEqual(models['K-Nearest Neighbors'].n_neighbors, 5)
        for name in ('Random Forest', 'Logistic Regression', 'Decision Tree'):
            self.assertEqual(models[name].random_state, 13)

    def test_insufficient_and_one_class_data_return_honest_empty_report(self):
        """Avoid fitting on tiny, one-class or unstratifiable labels instead of faking metrics."""
        X, y = evaluation_fixture()
        for features, labels in [(X.iloc[:0], y.iloc[:0]), (X.iloc[:49], y.iloc[:49]),
                                  (X, y * 0), (X, pd.Series([1] + [0] * 199)),
                                  (X, pd.Series([1] * 3 + [0] * 197))]:
            result = recommender.evaluate_models(features, labels)
            self.assertTrue(result.empty)
            self.assertFalse(result.attrs['available'])
            self.assertTrue(result.attrs['reason'])
            self.assertNotIn('test_metrics', result.attrs)

    def test_invalid_inputs_and_undefined_metric_handling(self):
        """Reject invalid data and define zero scores for missing predictions."""
        X, y = evaluation_fixture()
        for features, labels in [(X.iloc[:-1], y), (X, y * 2), (X * float('nan'), y)]:
            with self.assertRaises(ValueError):
                recommender.evaluate_models(features, labels)
        metrics = recommender._classification_metrics([0, 1], [0, 0])
        self.assertAlmostEqual(metrics['precision'], 0.25)
        self.assertAlmostEqual(metrics['recall'], 0.5)
        self.assertAlmostEqual(metrics['f1'], 1 / 3)

    def test_comparison_and_top_ten_chart_data(self):
        """Match chart bars to F1 scores and retain only the ten largest feature importances."""
        rows = []
        for name in recommender._comparison_models():
            rows.extend([{'model': name, 'scaled': False, 'val_f1': 0.4},
                         {'model': name, 'scaled': True, 'val_f1': 0.6}])
        comparison = recommender.plot_model_comparison(pd.DataFrame(rows))
        self.assertEqual(len(comparison.axes[0].patches), 10)
        for bar in comparison.axes[0].patches[:5]:
            self.assertAlmostEqual(bar.get_height(), 0.4)
        values = pd.DataFrame({'feature': [f'feature {i}' for i in range(12)],
                               'importance': [i / 66 for i in range(12)]})
        chart = recommender.plot_feature_importances(values)
        self.assertEqual(len(chart.axes[0].patches), 10)
        self.assertAlmostEqual(chart.axes[0].patches[0].get_width(), 11 / 66)
        self.assertTrue(chart.axes[0].yaxis_inverted())
        self.assertEqual(recommender.plt.get_fignums(), [])
